'use strict';

const { getSettings } = require('../config/alpha-pinning.cjs');

function certificatePinnerSource(snapshot) {
  const active = getSettings(snapshot);
  return `package com.titaniumsportgym.app

import android.content.Context
import com.facebook.react.modules.network.OkHttpClientProvider
import okhttp3.CertificatePinner

// Generated by the Expo config plugin. Same verified pin as the Android XML.
internal object TitaniumCertificatePinning {
  fun install(context: Context) {
    val pinner = CertificatePinner.Builder()
      .add("${active.host}", ${active.pins.map(pin => `"sha256/${pin}"`).join(', ')})
      .build()
    val applicationContext = context.applicationContext
    OkHttpClientProvider.setOkHttpClientFactory {
      // Preserve React Native's cookies, cache and timeouts; no custom TLS trust.
      OkHttpClientProvider.createClientBuilder(applicationContext)
        .certificatePinner(pinner)
        .build()
    }
  }
}
`;
}

module.exports = { certificatePinnerSource };
